# PrepDay: minimal daily prep list and waste log for small restaurants
import json, datetime, sys, pathlib

DATA = pathlib.Path("prepday.json")

def load():
    return json.loads(DATA.read_text()) if DATA.exists() else {"items": {}, "log": []}

def save(d):
    DATA.write_text(json.dumps(d, indent=2))

def prep_list(d, covers):
    # covers = expected guests; par level per item scaled by expected covers
    out = []
    for name, it in d["items"].items():
        need = round(it["par_per_cover"] * covers - it.get("on_hand", 0), 1)
        if need > 0:
            out.append(f"{name}: prep {need} {it['unit']}")
    return out

def log_waste(d, name, qty, cost_per_unit):
    d["log"].append({"date": str(datetime.date.today()), "item": name,
                     "qty": qty, "cost": round(qty * cost_per_unit, 2)})

def weekly_waste(d):
    week = datetime.date.today().isocalendar()[1]
    return sum(e["cost"] for e in d["log"]
               if datetime.date.fromisoformat(e["date"]).isocalendar()[1] == week)

if __name__ == "__main__":
    d = load()
    if len(sys.argv) > 1 and sys.argv[1] == "prep":
        for line in prep_list(d, int(sys.argv[2])):
            print(line)
    elif len(sys.argv) > 1 and sys.argv[1] == "waste":
        log_waste(d, sys.argv[2], float(sys.argv[3]), float(sys.argv[4]))
        save(d)
        print(f"This week's waste: ${weekly_waste(d):.2f}")
    else:
        print("usage: app.py prep <covers> | waste <item> <qty> <cost_per_unit>")
EOF
